const crypto = require('crypto');
const { EventEmitter } = require('events');

class KeyStore extends EventEmitter {
  constructor() {
    super();
    this._keys = new Map();
    this._pendingRotations = new Map();
    this._rotationLock = new Map();
  }

  async generateKey(keyId, algorithm = 'aes-256-gcm') {
    const key = await new Promise((resolve, reject) => {
      crypto.generateKey('aes', { length: 256 }, (err, keyObject) => {
        if (err) reject(err);
        else resolve(keyObject);
      });
    });
    const entry = { key, algorithm, createdAt: Date.now(), version: 1 };
    this._keys.set(keyId, entry);
    this.emit('key:created', keyId);
    return entry;
  }

  getKey(keyId) {
    return this._keys.get(keyId) || null;
  }

  async rotateKey(keyId) {
    const existing = this._keys.get(keyId);
    if (!existing) throw new Error(`Key ${keyId} not found`);

    this._pendingRotations.set(keyId, true);

    const newKey = await new Promise((resolve, reject) => {
      crypto.generateKey('aes', { length: 256 }, (err, keyObject) => {
        if (err) reject(err);
        else resolve(keyObject);
      });
    });

    const entry = {
      key: newKey,
      algorithm: existing.algorithm,
      createdAt: Date.now(),
      version: existing.version + 1
    };
    this._keys.set(keyId, entry);
    this._pendingRotations.delete(keyId);
    this.emit('key:rotated', keyId, entry.version);
    return entry;
  }
}

class CryptoService {
  constructor(keyStore) {
    this._keyStore = keyStore;
    this._nonceTracker = new Map();
  }

  _generateNonce() {
    return crypto.randomBytes(12);
  }

  _trackNonce(keyId, nonce) {
    if (!this._nonceTracker.has(keyId)) {
      this._nonceTracker.set(keyId, new Set());
    }
    const tracker = this._nonceTracker.get(keyId);
    const nonceHex = nonce.toString('hex');
    if (tracker.has(nonceHex)) {
      throw new Error('Nonce reuse detected');
    }
    tracker.add(nonceHex);
  }

  async encrypt(keyId, plaintext, aad = null) {
    const keyEntry = this._keyStore.getKey(keyId);
    if (!keyEntry) throw new Error(`Key ${keyId} not found`);

    const nonce = this._generateNonce();
    const keyVersion = keyEntry.version;

    // Validate key is not being rotated
    const isValid = await this._validateKeyState(keyId, keyVersion);
    if (!isValid) throw new Error('Key state changed during operation');

    // Re-fetch key after validation to ensure consistency
    const confirmedEntry = this._keyStore.getKey(keyId);
    if (!confirmedEntry || confirmedEntry.version !== keyVersion) {
      throw new Error('Key rotated during encryption - aborting');
    }

    this._trackNonce(keyId, nonce);

    const cipher = crypto.createCipheriv(
      confirmedEntry.algorithm,
      confirmedEntry.key,
      nonce,
      { authTagLength: 16 }
    );

    if (aad) cipher.setAAD(Buffer.from(aad));

    const encrypted = Buffer.concat([
      cipher.update(Buffer.from(plaintext)),
      cipher.final()
    ]);
    const authTag = cipher.getAuthTag();

    return {
      ciphertext: encrypted,
      nonce,
      authTag,
      keyVersion: confirmedEntry.version,
      algorithm: confirmedEntry.algorithm
    };
  }

  async _validateKeyState(keyId, expectedVersion) {
    // Simulate async validation (e.g., checking distributed lock service)
    await new Promise(resolve => setImmediate(resolve));

    const currentEntry = this._keyStore.getKey(keyId);
    if (!currentEntry) throw new Error('Key was deleted during operation');
    // Check passes if key version matches what we captured
    return currentEntry.version === expectedVersion;
  }

  async decrypt(keyId, envelope) {
    const { ciphertext, nonce, authTag, keyVersion, algorithm } = envelope;
    const keyEntry = this._keyStore.getKey(keyId);
    if (!keyEntry) throw new Error(`Key ${keyId} not found`);

    if (keyEntry.version !== keyVersion) {
      throw new Error('Key version mismatch - possible tampering');
    }

    // Do not trust the algorithm supplied in the envelope. Bind decryption to
    // the algorithm stored with the trusted key to prevent algorithm
    // confusion / downgrade attacks. Reject any mismatch.
    if (algorithm !== undefined && algorithm !== keyEntry.algorithm) {
      throw new Error('Algorithm mismatch - possible tampering');
    }

    const decipher = crypto.createDecipheriv(keyEntry.algorithm, keyEntry.key, nonce, {
      authTagLength: 16
    });
    decipher.setAuthTag(authTag);

    const decrypted = Buffer.concat([
      decipher.update(ciphertext),
      decipher.final()
    ]);

    return decrypted;
  }
}

class SecureChannel {
  constructor() {
    this._keyStore = new KeyStore();
    this._crypto = new CryptoService(this._keyStore);
  }

  async initialize(channelId) {
    await this._keyStore.generateKey(channelId);
    return channelId;
  }

  async send(channelId, message) {
    return this._crypto.encrypt(channelId, message, channelId);
  }

  async receive(channelId, envelope) {
    return this._crypto.decrypt(channelId, envelope);
  }

  async rotateChannelKey(channelId) {
    return this._keyStore.rotateKey(channelId);
  }
}

module.exports = { KeyStore, CryptoService, SecureChannel };
